import{_ as a,o as n,c as e,S as l}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse('{"title":"Archlinux下使用airbase和dhcpd建立虚拟AP","description":"Linux 下的 wicd 本身自带一个创建 Ad-Hoc network 功能的,但是这个功能太不实用了, 首先,Ad-Hoc 只能把笔记本的无线通过有线进行共享,而且 Ad-Hoc 网络无法被安卓原生系统识别,CM 倒是可以用.host…","frontmatter":{"title":"Archlinux下使用airbase和dhcpd建立虚拟AP","date":"2013-08-26 21:29","comments":true,"archives":2013,"tags":["linux","airbase"]},"headers":[],"relativePath":"posts/2013-08-26-archlinux-airbase-create-fakeap/index.md","filePath":"posts/2013/2013-08-26-Archlinux-airbase-create-FakeAP.md"}'),p={name:"posts/2013-08-26-archlinux-airbase-create-fakeap/index.md"};function o(r,s,t,c,i,d){return n(),e("div",null,[...s[0]||(s[0]=[l(`<p>Linux 下的 wicd 本身自带一个创建 Ad-Hoc network 功能的,但是这个功能太不实用了, 首先,Ad-Hoc 只能把笔记本的无线通过有线进行共享,而且 Ad-Hoc 网络无法被安卓原生系统识别,CM 倒是可以用.hostapd 也是一样.只能把有线网络通过无线进行共享. 但是我经常是电脑连接 WIFI,并且想把 WIFI 共享给手机进行使用,于是我又开始折腾了 &gt;_&gt;</p><h2 id="首先安装所需要的软件" tabindex="-1">首先安装所需要的软件 <a class="header-anchor" href="#首先安装所需要的软件" aria-label="Permalink to &quot;首先安装所需要的软件&quot;">​</a></h2><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>net-tools</span></span>
<span class="line"><span>iptables</span></span>
<span class="line"><span>aircrack-ng</span></span>
<span class="line"><span>dhcpd</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="然后启动虚拟-ap" tabindex="-1">然后启动虚拟 AP <a class="header-anchor" href="#然后启动虚拟-ap" aria-label="Permalink to &quot;然后启动虚拟 AP&quot;">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">airmon-ng</span><span style="color:#032F62;"> start</span><span style="color:#032F62;"> wlp5s0</span><span style="color:#6A737D;"> # 启动无线网卡的monitor模式 wlp5s0是我网卡的设备名 这时候会看到输出 monitor mode enabled on mon0 mon0便是虚拟出来的一个网卡设备</span></span>
<span class="line"><span style="color:#6F42C1;">airbase-ng</span><span style="color:#005CC5;"> -e</span><span style="color:#032F62;"> FreeWifi</span><span style="color:#005CC5;">  -v</span><span style="color:#032F62;"> mon0</span><span style="color:#24292E;"> &amp; </span><span style="color:#6A737D;"># 在mon0设备上创建Fake AP -e选项是设置SSID名字 -v是启动DEBUG模式 最后是设备名字,想进行后台运行请按Ctrl+D</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="激活-tap-insterface-并添加路由表" tabindex="-1">激活 tap insterface 并添加路由表 <a class="header-anchor" href="#激活-tap-insterface-并添加路由表" aria-label="Permalink to &quot;激活 tap insterface 并添加路由表&quot;">​</a></h2><p>执行上面的名字之后会输出 Created tap interface at0 然后执行下面的命令</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">ifconfig</span><span style="color:#032F62;"> at0</span><span style="color:#032F62;"> up</span></span>
<span class="line"><span style="color:#6F42C1;">ifconfig</span><span style="color:#032F62;"> at0</span><span style="color:#005CC5;"> 10.0.0.254</span><span style="color:#032F62;"> netmask</span><span style="color:#005CC5;"> 255.255.255.0</span></span>
<span class="line"><span style="color:#6F42C1;">route</span><span style="color:#032F62;"> add</span><span style="color:#005CC5;"> -net</span><span style="color:#005CC5;"> 10.0.0.0</span><span style="color:#032F62;"> netmask</span><span style="color:#005CC5;"> 255.255.255.0</span><span style="color:#032F62;"> gw</span><span style="color:#005CC5;"> 10.0.0.254</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="设置-iptables" tabindex="-1">设置 iptables <a class="header-anchor" href="#设置-iptables" aria-label="Permalink to &quot;设置 iptables&quot;">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">iptables</span><span style="color:#005CC5;"> --flush</span></span>
<span class="line"><span style="color:#6F42C1;">iptables</span><span style="color:#005CC5;"> --table</span><span style="color:#032F62;"> nat</span><span style="color:#005CC5;"> --flush</span></span>
<span class="line"><span style="color:#6F42C1;">iptables</span><span style="color:#005CC5;"> --delete-chain</span></span>
<span class="line"><span style="color:#6F42C1;">iptables</span><span style="color:#005CC5;"> --table</span><span style="color:#032F62;"> nat</span><span style="color:#005CC5;"> --delete-chain</span></span>
<span class="line"><span style="color:#6F42C1;">iptables</span><span style="color:#005CC5;"> -P</span><span style="color:#032F62;"> FORWARD</span><span style="color:#032F62;"> ACCEPT</span></span>
<span class="line"><span style="color:#6F42C1;">iptables</span><span style="color:#005CC5;"> -t</span><span style="color:#032F62;"> nat</span><span style="color:#005CC5;"> -A</span><span style="color:#032F62;"> POSTROUTING</span><span style="color:#005CC5;"> -o</span><span style="color:#032F62;"> wlp5s0</span><span style="color:#005CC5;"> -j</span><span style="color:#032F62;"> MASQUERADE</span></span>
<span class="line"><span style="color:#6F42C1;">//这里wlp5s0是我额外要连接到互联网的网卡设备名</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="配置-dns-服务器" tabindex="-1">配置 DNS 服务器 <a class="header-anchor" href="#配置-dns-服务器" aria-label="Permalink to &quot;配置 DNS 服务器&quot;">​</a></h2><p>没有 DNS 服务器即使能搜到 AP 也无法连接,因为获取不到 IP 地址. 首先列出 <code>dhcpd.conf</code> 的内容</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">ddns-update-style</span><span style="color:#032F62;"> none</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6F42C1;">default-lease-time</span><span style="color:#005CC5;"> 600</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6F42C1;">max-lease-time</span><span style="color:#005CC5;"> 7200</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6F42C1;">authoritative</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6F42C1;">subnet</span><span style="color:#005CC5;"> 10.0.0.0</span><span style="color:#032F62;"> netmask</span><span style="color:#005CC5;"> 255.255.255.0</span><span style="color:#032F62;"> {</span></span>
<span class="line"><span style="color:#6F42C1;">option</span><span style="color:#032F62;"> subnet-mask</span><span style="color:#005CC5;"> 255.255.255.0</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6F42C1;">option</span><span style="color:#032F62;"> broadcast-address</span><span style="color:#005CC5;"> 10.0.0.255</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6F42C1;">option</span><span style="color:#032F62;"> routers</span><span style="color:#005CC5;"> 10.0.0.254</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6F42C1;">option</span><span style="color:#032F62;"> domain-name-servers</span><span style="color:#005CC5;"> 114.114.114.114</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6F42C1;">range</span><span style="color:#005CC5;"> 10.0.0.1</span><span style="color:#005CC5;"> 10.0.0.140</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>然后执行下面的命令</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#005CC5;">echo</span><span style="color:#D73A49;"> &gt;</span><span style="color:#032F62;"> &#39;/var/lib/dhcp/dhcpd.leases&#39;</span></span>
<span class="line"><span style="color:#6F42C1;">dhcpd</span><span style="color:#005CC5;"> -d</span><span style="color:#005CC5;"> -f</span><span style="color:#005CC5;"> -cf</span><span style="color:#032F62;"> dhcpd.conf</span><span style="color:#032F62;"> at0</span><span style="color:#24292E;"> &amp;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="最后启用-ip-forwarding" tabindex="-1">最后启用 IP forwarding <a class="header-anchor" href="#最后启用-ip-forwarding" aria-label="Permalink to &quot;最后启用 IP forwarding&quot;">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#005CC5;">echo</span><span style="color:#032F62;"> &quot;1&quot;</span><span style="color:#D73A49;"> &gt;</span><span style="color:#032F62;"> /proc/sys/net/ipv4/ip_forward</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>虽然能创建虚拟 AP,但是安卓原生系统连接获取到 IP 一段时间后又会自动掉线,原因不明,希望知道的菊苣能告诉咱一声~</p>`,19)])])}const y=a(p,[["render",o]]);export{u as __pageData,y as default};
